// StrictMode: setup, cleanup, setup again. The first request is aborted,
// so only one response can set state.
useEffect(() => {
  const controller = new AbortController();

  fetch("/api/hotels", { signal: controller.signal })
    .then((response) => response.json())
    .then(setHotels)
    .catch((error) => {
      if (error.name !== "AbortError") setError("Could not load hotels.");
    });

  return () => controller.abort();
}, []);

import { useEffect, useState } from "react";

// Data shape: hotels = [{ hotel_id, name, city, stars }]
export default function Hotels({ city }) {
  const [hotels, setHotels] = useState([]);
  const [error, setError] = useState("");

  useEffect(() => {
    const controller = new AbortController();

    async function load() {
      try {
        const response = await fetch(
          `/api/hotels?city=${encodeURIComponent(city)}`,
          { signal: controller.signal }
        );
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        setHotels(await response.json());
      } catch (caught) {
        if (caught.name !== "AbortError") setError("Could not load hotels.");
      }
    }

    load();
    return () => controller.abort();
  }, [city]);

  return error ? <p className="error">{error}</p> : <List items={hotels} />;
}

// Data shape: results = [{ hotel_id, name }]
useEffect(() => {
  let ignore = false; // one flag per run, closed over by the handlers

  fetch(`/api/search?word=${encodeURIComponent(word)}`)
    .then((response) => response.json())
    .then((data) => {
      if (!ignore) setResults(data);
    });

  return () => {
    ignore = true; // this run was replaced, drop its response
  };
}, [word]);

