Type `bu`, the request for `bu` is slow. Type `bud`, the request for `bud` answers first and fills the list. Then `bu` answers and overwrites it. The input says `bud` and the list shows hotels from `bu`.

The flag fixes the order, the controller fixes the wasted bandwidth. Use both when the payload is large, the flag alone when you only care about correctness.

```jsx
useEffect(() => {
  const controller = new AbortController();

  async function load() {
    const response = await fetch(url, { signal: controller.signal });
    const data = await response.json();
    setRows(data); // unreachable for an aborted run
  }

  load().catch(() => {});
  return () => controller.abort();
}, [url]);
```

A guard without a cleanup is not a guard. The flag has to be flipped by the cleanup, because that is the only place React tells you the run is over.

example:
// Wrong: the callback returns a Promise, so React never gets a cleanup.
useEffect(async () => {
  const data = await getHotels();
  setHotels(data);
}, []);

// Right: an inner async function, called and not awaited.
useEffect(() => {
  async function load() {
    const data = await getHotels();
    setHotels(data);
  }

  load();
  return () => { /* cleanup stays reachable */ };
}, []);

// Data shape: seconds: number
export default function Stopwatch() {
  const [seconds, setSeconds] = useState(0);
  const [running, setRunning] = useState(false);

  useEffect(() => {
    if (!running) return;

    const id = setInterval(() => {
      // Functional update: the interval never reads a frozen seconds value.
      setSeconds((value) => value + 1);
    }, 1000);

    return () => clearInterval(id);
  }, [running]);

  return (
    <>
      <p>{seconds} s</p>
      <button onClick={() => setRunning(!running)}>
        {running ? "Stop" : "Start"}
      </button>
    </>
  );
}

import { useEffect, useState } from "react";

// Data shape: online: boolean
function useOnline() {
  const [online, setOnline] = useState(navigator.onLine);

  useEffect(() => {
    function update() {
      setOnline(navigator.onLine);
    }

    window.addEventListener("online", update);
    window.addEventListener("offline", update);

    return () => {
      window.removeEventListener("online", update);
      window.removeEventListener("offline", update);
    };
  }, []);

  return online;
}

body:
Declaring the handler inside the effect keeps it out of the dependency array and gives both `add` and `remove` the same reference. A handler declared in the component body is a new function every render, so `[update]` resubscribes on every render.

When the handler reads a component value, that value goes in the array:

```jsx
useEffect(() => {
  function onMessage(event) {
    append(event.data, roomId);
  }

  socket.on("message", onMessage);
  return () => socket.off("message", onMessage);
}, [roomId]);
```

Without `[roomId]` the first room id is captured forever. The user switches rooms, the socket stays in the old one, and the bug looks like a server problem.

